SELECT CASE WHEN unit_price >= 400 THEN 'high' WHEN unit_price >= 170 THEN 'mid' ELSE 'low' END AS unit_price_bucket, product_id, CASE WHEN quantity >= 8 THEN 'high' WHEN quantity >= 2 THEN 'mid' ELSE 'low' END AS quantity_bucket, MIN(unit_price) AS min_unit_price, MAX(unit_price) - MIN(unit_price) AS unit_price_range, COUNT(quantity) AS quantity_count FROM order_items WHERE quantity < 7 AND (quantity <= 3 OR unit_price IS NOT NULL) GROUP BY CASE WHEN unit_price >= 400 THEN 'high' WHEN unit_price >= 170 THEN 'mid' ELSE 'low' END, product_id, CASE WHEN quantity >= 8 THEN 'high' WHEN quantity >= 2 THEN 'mid' ELSE 'low' END ORDER BY quantity_bucket, unit_price_range DESC, unit_price_bucket, product_id LIMIT 5
